-- Instrument 7: Opportunity Prioritization & Scenario Model
UPDATE assessment_template_versions tv
SET schema_definition=$schema${"instrument_number":7,"template_name":"Opportunity Prioritization & Scenario Model","description":"An advisor-controlled decision model that ranks validated opportunities using transparent weighted criteria and models conservative, base and upside scenarios only where assumptions and evidence support quantification.","schema_status":"active","sections":[{"id":"decision_rules","title":"Decision rules & portfolio assumptions","description":"Set the scope and assumptions used to compare opportunities consistently.","questions":[{"key":"pri_currency","label":"Scenario currency (e.g. USD)","type":"text","required":true},{"key":"pri_horizon","label":"Scenario horizon","type":"select","required":true,"options":["12 months","24 months","36 months","Other / defined below"]},{"key":"pri_horizon_other","label":"Other scenario horizon / scope","type":"text","required":false},{"key":"pri_baseline","label":"Baseline period and source","type":"textarea","required":true},{"key":"pri_model_assumptions","label":"Portfolio-wide assumptions and exclusions","type":"textarea","required":true},{"key":"pri_overlap","label":"Potential overlap / double-counting between opportunities","type":"textarea","required":true},{"key":"pri_constraints","label":"Budget, capacity, timing and strategic constraints","type":"textarea","required":false}]},{"id":"opportunity_1","title":"1. Opportunity 1","description":"Assess one candidate opportunity. Ratings are advisor judgments and must be supported by the rationale and evidence.","questions":[{"key":"op1_name","label":"Opportunity name","type":"text","required":true},{"key":"op1_cause","label":"Root cause addressed","type":"textarea","required":true},{"key":"op1_outcome","label":"Expected outcome and measurable indicator","type":"textarea","required":true},{"key":"op1_impact","label":"Potential impact","type":"select","required":true,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op1_evidence","label":"Evidence confidence","type":"select","required":true,"options":["1 — Hypothesis only","2 — Limited / indirect","3 — Partial supporting evidence","4 — Strong evidence","5 — Verified and corroborated"]},{"key":"op1_effort","label":"Implementation effort (higher = harder)","type":"select","required":true,"options":["1 — Minimal","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op1_time","label":"Time to value","type":"select","required":true,"options":["1 — Under 30 days","2 — 30–60 days","3 — 60–90 days","4 — 3–6 months","5 — More than 6 months"]},{"key":"op1_risk","label":"Implementation risk (higher = riskier)","type":"select","required":true,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op1_fit","label":"Strategic fit","type":"select","required":true,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op1_readiness","label":"Owner / organization readiness","type":"select","required":true,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op1_dependency","label":"Key dependencies and prerequisites","type":"textarea","required":false},{"key":"op1_owner","label":"Proposed accountable owner","type":"text","required":false},{"key":"op1_assumptions","label":"Scoring rationale, trade-offs and assumptions","type":"textarea","required":true},{"key":"op1_benefit_basis","label":"Scenario benefit basis","type":"select","required":false,"options":["Revenue","Gross profit / contribution","Operating cost savings","Cash flow / working capital","Risk avoidance (not guaranteed savings)","Capacity / non-financial benefit","Not yet quantifiable"]},{"key":"op1_conservative","label":"Conservative annual gross benefit (currency amount)","type":"number","required":false},{"key":"op1_base","label":"Base annual gross benefit (currency amount)","type":"number","required":false},{"key":"op1_upside","label":"Upside annual gross benefit (currency a