number","required":false},{"key":"op3_upside","label":"Upside annual gross benefit (currency amount)","type":"number","required":false},{"key":"op3_recurring_cost","label":"Estimated annual recurring cost (same currency)","type":"number","required":false},{"key":"op3_one_time_cost","label":"Estimated one-time implementation cost (same currency)","type":"number","required":false},{"key":"op3_realization","label":"Expected time until benefits begin (months)","type":"number","required":false}]},{"id":"opportunity_4","title":"4. Opportunity 4","description":"Assess one candidate opportunity. Ratings are advisor judgments and must be supported by the rationale and evidence.","questions":[{"key":"op4_name","label":"Opportunity name","type":"text","required":false},{"key":"op4_cause","label":"Root cause addressed","type":"textarea","required":false},{"key":"op4_outcome","label":"Expected outcome and measurable indicator","type":"textarea","required":false},{"key":"op4_impact","label":"Potential impact","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op4_evidence","label":"Evidence confidence","type":"select","required":false,"options":["1 — Hypothesis only","2 — Limited / indirect","3 — Partial supporting evidence","4 — Strong evidence","5 — Verified and corroborated"]},{"key":"op4_effort","label":"Implementation effort (higher = harder)","type":"select","required":false,"options":["1 — Minimal","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op4_time","label":"Time to value","type":"select","required":false,"options":["1 — Under 30 days","2 — 30–60 days","3 — 60–90 days","4 — 3–6 months","5 — More than 6 months"]},{"key":"op4_risk","label":"Implementation risk (higher = riskier)","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op4_fit","label":"Strategic fit","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op4_readiness","label":"Owner / organization readiness","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op4_dependency","label":"Key dependencies and prerequisites","type":"textarea","required":false},{"key":"op4_owner","label":"Proposed accountable owner","type":"text","required":false},{"key":"op4_assumptions","label":"Scoring rationale, trade-offs and assumptions","type":"textarea","required":false},{"key":"op4_benefit_basis","label":"Scenario benefit basis","type":"select","required":false,"options":["Revenue","Gross profit / contribution","Operating cost savings","Cash flow / working capital","Risk avoidance (not guaranteed savings)","Capacity / non-financial benefit","Not yet quantifiable"]},{"key":"op4_conservative","label":"Conservative annual gross benefit (currency amount)","type":"number","required":false},{"key":"op4_base","label":"Base annual gross benefit (currency amount)","type":"number","required":false},{"key":"op4_upside","label":"Upside annual gross benefit (currency amount)","type":"number","required":false},{"key":"op4_recurring_cost","label":"Estimated annual recurring cost (same currency)","type":"number","required":false},{"key":"op4_one_time_cost","label":"Estimated one-time implementation cost (same currency)","type":"number","required":false},{"key":"op4_realization","label":"Expected time until benefits begin (months)","type":"number","required":false}]},{"id":"opportunity_5","title":"5. Opportunity 5","description":"Assess one candidate opportunity. Ratings are advisor judgments and must be supported by the rationale and evidence.","questions":[{"key":"op5_name","label":"Opportunity name","type":"text","required":false},{"key":"op5_cause","label":"Root cause addressed","type":"textarea","required":false},{"key":"op5_outcome","label":"Expected outcome and measurable indicator","type":"textarea","required":false},{"key":"op5_impact","label":"Potential impact","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op5_evidence","label":"Evidence confidence","type":"select","required":false,"options":["1 — Hypothesis only","2 — Limited / indirect","3 — Partial supporting evidence","4 — Strong evidence","5 — Verified and corroborated"]},{"key":"op5_effort","label":"Implementation effort (higher = harder)","type":"select","required":false,"options":["1 — Minimal","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op5_time","label":"Time to value","type":"select","required":false,"options":["1 — Under 30 days","2 — 30–60 days","3 — 60–90 days","4 — 3–6 months","5 — More than 6 months"]},{"key":"op5_risk","label":"Implementation risk (higher = riskier)","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op5_fit","label":"Strategic fit","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op5_readiness","label":"Owner / organization readiness","type":"select","required":false,"options":["1 — Very low","2 — Low","3 — Moderate","4 — High","5 — Very high"]},{"key":"op5_dependency","label":"Key dependencies and prerequisites","type":"textarea","required":false},{"key":"op5_owner","label":"Proposed accountable owner","type":"text","required":false},{"key":"op5_assumptions","label":"Scoring rationale, trade-offs and assumptions","type":"textarea","required":false},{"key":"op5_benefit_basis","label":"Scenario benefit basis","type":"select","required":false,"options":["Revenue","Gross profit / contribution","Operating cost savings","Cash flow / working capital","Risk avoidance (not guaranteed savings)","Capacity / non-financial benefit","Not yet quantifiable"]},{"key":"op5_conservative","label":"Conservative annual gross benefit (currency amount)","type":"number","required":false},{"key":"op5_base","label":"Base annual gross benefit (currency amount)","type":"number","required":false},{"key":"op5_upside","label":"Upside annual gross benefit (currency amount)","type":"number","required":false},{"key":"op5_recurring_cost","label":"Estimated annual recurring cost (same currency)","type":"number","required":false},{"key":"op5_one_time_cost","label":"Estimated one-time implementation cost (same currency)","type":"number","required":false},{"key":"op5_realization","label":"Expected time until benefits begin (months)","type":"number","required":false}]},{"id":"portfolio_synthesis","title":"Portfolio synthesis & decision","description":"Review the ranked opportunity set, sequencing, trade-offs and owner decisions.","questions":[{"key":"pri_portfolio_summary","label":"Portfolio summary and recommended sequence","type":"textarea","required":true},{"key":"pri_quick_wins","label":"Quick wins and low-regret tests","type":"textarea","required":false},{"key":"pri_prerequisites","label":"Prerequisites and critical-path dependencies","type":"textarea","required":true},{"key":"pri_not_now","label":"Opportunities deferred or rejected and rationale","type":"textarea","required":false},{"key":"pri_owner_decisions","label":"Decisions required from owner / leadership","type":"textarea","required":true},{"key":"pri_validation","label":"Validation plan before committing investment","type":"textarea","required":true},{"key":"pri_advisor_confidence","label":"Advisor confidence in ranking and scenarios","type":"select","required":true,"options":["High — consistent inputs and sufficient evidence","Moderate — useful ranking with material assumptions","Low — preliminary ranking; validate before commitment","Insufficient — do not rely on ranking yet"]}]}],"assessment_policy":"Priority scores are transparent decision aids, not objective truth or forecasts. Score only populated opportunities. The deterministic weighted score is: impact 25%, evidence confidence 15%, effort ease 15%, time-to-value 10%, risk manageability 10%, strategic fit 15%, readiness 10%. Each input is 1–5; effort, time and risk are reverse-scored (6 minus rating). Unknown values remain unscored, never zero. Scenario benefits and costs are optional, currency-specific estimates; distinguish revenue from gross profit, savings, working capital, risk avoidance and non-financial outcomes. Do not aggregate incompatible benefit bases, count overlapping benefits twice, or present scenario values as guaranteed outcomes. One-time implementation cost is separate from recurring annual cost. Payback is indicative only when base annual net benefit is positive and assumptions are complete."}$schema$::jsonb,
    scoring_definition=$score${"rating_owner":"advisor","missing_data_policy":"Unknown inputs are excluded from scoring, not scored as zero.","priority_formula":{"impact":0.25,"evidence":0.15,"effort_ease":0.15,"time_to_value":0.1,"risk_manageability":0.1,"strategic_fit":0.15,"readiness":0.1},"reverse_scored":["effort","time","risk"],"scenario_policy":"Conservative/base/upside values are optional assumptions, not forecasts or guaranteed outcomes. Benefits must use a consistent basis and currency. One-time costs are separate from annual recurring costs. No aggregation across incompatible benefit bases or overlapping opportunities."}$score$::jsonb,
    published_at=COALESCE(tv.published_at,now())
FROM assessment_templates t
WHERE tv.template_id=t.id AND t.instrument_number=7 AND tv.version_number=t.current_version;
